# ---- output ----
def dur(t):
    if t in ("—",): return 2.0
    p = t.count("(pause)"); w = len(re.sub(r"\(pause\)", "", t).split())
    return max(1.8, w / 2.4) + 1.4 * p
rows, t0 = [], 0.0
for i, (text, see, meth, refs, st) in zip(LAB, F):
    meth = re.sub(r"#([a-z0-9-]+)", lambda m: "#" + str(KEYS.get(m.group(1), "??" + m.group(1))), meth)
    d = dur(text); rows.append((i, t0, text, see, meth, refs, st)); t0 += d
kinds = {}
for r in rows:
    k = r[4].split("←")[0].split(" ")[0]; k = "NEW" if k.startswith("NEW") else k; kinds[k] = kinds.get(k, 0) + 1
mm = lambda s: f"{int(s//60)}:{s%60:04.1f}"
out = ["# شات‌لیست STILLCUT · فصل ۱ قسمت ۲ (script-en-v7)", "",
       f"**{len(rows)} قاب · حدود {mm(t0)}** · " + " · ".join(f"{k} {v}" for k, v in sorted(kinds.items(), key=lambda x: -x[1])), "",
       "> ستون **وضعیت** از دفتر وضعیت (ledger.md) می‌آید و در پرامپت‌ها خودکار به جمله تبدیل می‌شود. W=scar-R یعنی جای زخم روی ساعد **راست**، بدون باند.", ""]
for i, a, text, see, meth, refs, st in rows:
    if any(text.startswith(h) for h in ("Day forty-nine.", "Forty days since", "Back home, sixty-six", "Back in the tunnel, the last fish", "With food in your stomach", "Now it has to be buried", "The cold is getting worse.", "A few days later, Pip", "North Dakota.")):
        out += ["", "### " + {"Day forty-nine.": "۰ · Seven Fish", "Forty days since": "۱ · The Last of Them", "Back home, sixty-six": "۲ · Meanwhile",
                 "Back in the tunnel, the last fish": "۳ · Eat What Eats the Dead", "With food in your stomach": "۴ · A Message for Mom",
                 "Now it has to be buried": "۵ · The River at Dawn", "The cold is getting worse.": "۶ · The Night the Fire Died",
                 "A few days later, Pip": "۷ · Not Alone", "North Dakota.": "۸ · Sixty-Six Million Years Later"}[next(h for h in ("Day forty-nine.", "Forty days since", "Back home, sixty-six", "Back in the tunnel, the last fish", "With food in your stomach", "Now it has to be buried", "The cold is getting worse.", "A few days later, Pip", "North Dakota.") if text.startswith(h))]]
    tag = "🆕 " if meth.startswith("NEW") else ""
    out.append(f"- **#{i}** · {mm(a)} · `{meth}` {tag}— {see}" + (f" · _رفرنس: {refs}_" if refs else "") + (f" · **وضعیت:** `{st}`" if st else ""))
    out.append(f"  > {text}")
open(os.path.join(H, "shotlist.md"), "w").write("\n".join(out) + "\n")
print(len(rows), "frames,", mm(t0), kinds)
print("unresolved:", [r[0] for r in rows if "??" in r[4]])
